create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, display_name text, timezone text not null default 'Europe/London', step_goal integer not null default 10000, goals jsonb not null default '[]', created_at timestamptz not null default now());
create table if not exists public.whoop_connections (user_id uuid primary key references auth.users(id) on delete cascade, access_token_encrypted text not null, refresh_token_encrypted text, expires_at timestamptz, scopes text[] not null default '{}', connected_at timestamptz not null default now(), updated_at timestamptz not null default now(), last_sync_at timestamptz);
create table if not exists public.whoop_records (user_id uuid not null references auth.users(id) on delete cascade, provider_id text not null, record_type text not null, provider_timestamp timestamptz, payload jsonb not null, synced_at timestamptz not null default now(), primary key (user_id, provider_id, record_type));
create table if not exists public.daily_activity (user_id uuid not null references auth.users(id) on delete cascade, date date not null, source text not null, steps integer, active_calories numeric, strain numeric, updated_at timestamptz not null default now(), primary key (user_id,date,source));
create table if not exists public.nutrition_targets (user_id uuid primary key references auth.users(id) on delete cascade, calories numeric, protein numeric, carbohydrates numeric, fats numeric);
create table if not exists public.foods (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, calories numeric, protein numeric, carbohydrates numeric, fats numeric, source text not null default 'user');
create table if not exists public.meals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, timing text, foods jsonb not null default '[]');
create table if not exists public.food_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, date date not null, meal_id uuid, food_id uuid, servings numeric not null default 1);
create table if not exists public.meal_plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, meals jsonb not null default '[]');
create table if not exists public.shopping_lists (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, items jsonb not null default '[]');
alter table public.profiles enable row level security; alter table public.whoop_connections enable row level security; alter table public.whoop_records enable row level security; alter table public.daily_activity enable row level security;
create policy "own profile" on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
create policy "own activity" on public.daily_activity for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own nutrition target" on public.nutrition_targets for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own foods" on public.foods for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own meals" on public.meals for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own food logs" on public.food_logs for all using (user_id = auth.uid()) with check (user_id = auth.uid());
